<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const leases=ref<any[]>([]),showModal=ref(false),result=ref<any>(null),queryID=ref(''),form=ref({lease_id:'',deposit_deduction:0,description:'',amount:0,meter_kind:'water',reading:0});async function init(){leases.value=(await api.get('/leases',{params:{page:1,page_size:100}})).data.items||[]}async function create(){const r=await api.post('/settlements',{lease_id:form.value.lease_id,deposit_deduction:form.value.deposit_deduction,items:[{kind:'move_out',description:form.value.description,amount:form.value.amount}],readings:[{kind:form.value.meter_kind,reading:form.value.reading}]});result.value={settlement:r.data,items:[],readings:[]};queryID.value=r.data.ID;showModal.value=false}async function load(){if(queryID.value)result.value=(await api.get(`/settlements/${queryID.value}`)).data}async function complete(){await api.post(`/settlements/${queryID.value}/complete`);await load()}onMounted(init)</script><template><div class="page"><div class="page-title"><div><h1>退租结算</h1><p>录入退租抄表、汇总费用、押金抵扣并恢复房源状态</p></div><button class="primary-button" @click="showModal=true">＋ 发起退租结算</button></div><section class="card"><div class="toolbar"><div><h3 style="margin:0">结算单查询</h3><p style="margin:6px 0 0;color:#8b97a9;font-size:12px">输入结算单编号查看费用明细和抄表记录</p></div><div class="toolbar-right"><div class="field"><input v-model="queryID" class="search-input" placeholder="请输入结算单 ID"></div><button class="secondary-button" @click="load">查询</button></div></div></section><section v-if="result" class="card"><div class="settlement-head"><div><span>结算状态</span><strong>{{result.settlement.Status}}</strong></div><div><span>费用合计</span><strong>{{result.settlement.Total}}</strong></div><div><span>押金抵扣</span><strong>{{result.settlement.DepositDeduction}}</strong></div><div><span>押金返还</span><strong>{{result.settlement.Refund}}</strong></div></div><h3>费用明细</h3><table class="data-table"><thead><tr><th>类型</th><th>说明</th><th>金额</th></tr></thead><tbody><tr v-for="x in result.items" :key="x.ID"><td>{{x.Kind}}</td><td>{{x.Description}}</td><td>{{x.Amount}}</td></tr></tbody></table><div class="modal-footer" style="padding-right:0"><button v-if="result.settlement.Status!=='completed'" class="primary-button" @click="complete">完成结算并恢复房态</button></div></section><div v-else class="card empty-state"><b>尚未选择结算单</b><span>可点击右上角发起退租结算，或输入已有结算单 ID 查询</span></div><div v-if="showModal" class="modal-mask" @click.self="showModal=false"><div class="modal"><div class="modal-header"><h3>发起退租结算</h3><button class="close-button" @click="showModal=false">×</button></div><div class="modal-body"><div class="form-grid"><label class="full"><span>退租租约 *</span><select v-model="form.lease_id"><option value="">请选择租约</option><option v-for="x in leases.filter(v=>['active','terminating','expired'].includes(v.Status))" :key="x.ID" :value="x.ID">{{x.PropertyID.slice(0,8)}} · {{String(x.EndDate).slice(0,10)}} · {{x.Status}}</option></select></label><label><span>费用金额 *</span><input v-model.number="form.amount" type="number" min="0"></label><label><span>押金抵扣</span><input v-model.number="form.deposit_deduction" type="number" min="0"></label><label class="full"><span>费用说明 *</span><input v-model="form.description" placeholder="例如：未结租金、水电费、维修费"></label><label><span>抄表类型</span><select v-model="form.meter_kind"><option value="water">水表</option><option value="electricity">电表</option><option value="gas">燃气表</option></select></label><label><span>退租读数</span><input v-model.number="form.reading" type="number"></label></div></div><div class="modal-footer"><button class="secondary-button" @click="showModal=false">取消</button><button class="primary-button" @click="create">生成结算单</button></div></div></div></div></template><style scoped>.settlement-head{display:grid;grid-template-columns:repeat(4,1fr);background:#f7fafc;border-radius:12px;margin-bottom:22px}.settlement-head div{padding:17px;border-right:1px solid #e5eaf1}.settlement-head div:last-child{border:0}.settlement-head span,.settlement-head strong{display:block}.settlement-head span{font-size:11px;color:#8996a8}.settlement-head strong{font-size:20px;margin-top:7px}</style>